int minimumOperations(int* nums, int numsSize) {
    int vis[101] = {0};
    vis[0] = 1;
    int ans = 0;
    for (int i = 0; i < numsSize; i++) {
        if (vis[nums[i]]) {
            continue;
        }
        vis[nums[i]] = 1;
        ans++;
    }
    return ans;
}

class Solution {
public:
    int minimumOperations(vector<int>& nums) {

        priority_queue<int, vector<int>, greater<int>>pq;
        int n=nums.size();
        int ans=0;
        int subFactor=0;

        for(int i=0; i<n; i++){
            pq.push(nums[i]);
        }

        while(pq.size()!=0){
            int temp=pq.top();
            temp=temp-subFactor;
            if(temp!=0)
                ans++;
            subFactor+=temp;
            pq.pop();
        }
        return ans;
    }
};

